import functools
import asyncio
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

# 1. Plain function
def plain_dep(q: str = "default"):
    return q

# 2. Async function
async def async_dep(q: str = "default"):
    return q

# 3. Callable class
class CallableDep:
    def __call__(self, q: str = "default"):
        return q

callable_dep = CallableDep()

# Partial versions
partial_plain = functools.partial(plain_dep, q="partial_plain")
partial_async = functools.partial(async_dep, q="partial_async")
partial_callable = functools.partial(callable_dep, q="partial_callable")

@app.get("/plain")
def read_plain(p: str = Depends(partial_plain)):
    return {"p": p}

@app.get("/async")
async def read_async(p: str = Depends(partial_async)):
    return {"p": p}

@app.get("/callable")
async def read_callable(p: str = Depends(partial_callable)):
    return {"p": p}

client = TestClient(app)

def test_partials():
    print("Testing partial plain...")
    assert client.get("/plain").json() == {"p": "partial_plain"}
    print("Testing partial async...")
    assert client.get("/async").json() == {"p": "partial_async"}
    print("Testing partial callable...")
    assert client.get("/callable").json() == {"p": "partial_callable"}
    print("All tests passed!")

if __name__ == "__main__":
    test_partials()

