import inspect
from fastapi.dependencies.utils import get_typed_signature

class CallableDep:
    def __call__(self, q: "MyType" = "default"):
        return q

class MyType:
    pass

dep = CallableDep()
sig = get_typed_signature(dep)
print(f"Annotation: {sig.parameters['q'].annotation}")

